	submitCRDT(t, s, "doc", CRDTTypeRegister, CRDTOp{ID: "r3", DeviceID: "dev-2", Version: 1, Value: json.RawMessage(`"other"`)})

	before, err := s.GetCRDTSnapshot("doc")
	if err != nil {
		t.Fatal(err)
