		t.Fatalf("remove replay after compaction = %v %+v, want idempotent", err, results)
	}
	if got := crdtStateValue(t, s, "doc"); got != `["apple","banana"]` {
		t.Fatalf("state after replayed remove = %s, want [\"apple\",\"banana\"]", got)
	}
	// Replaying the compacted add stays idempotent and resurrects nothing.
	results, err = s.SubmitCRDTOps("doc", CRDTTypeORSet, []CRDTOp{
		{ID: "o1", DeviceID: "dev-1", Action: CRDTORSetAdd, Element: "apple"},
	})
	if err != nil || results[0].Created {
		t.Fatalf("add replay after compaction = %v %+v, want idempotent", err, results)
	}
	if got := crdtStateValue(t, s, "doc"); got != `["apple","banana"]` {
		t.Fatalf("state after replayed add = %s", got)
	}
}

func TestCompactORSetFullyRemovedSet(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	registerDevices(t, s, "dev-1")

	submitCRDT(t, s, "doc", CRDTTypeORSet, CRDTOp{ID: "o1", DeviceID: "dev-1", Action: CRDTORSetAdd, Element: "apple"})
	submitCRDT(t, s, "doc", CRDTTypeORSet, CRDTOp{ID: "o2", DeviceID: "dev-1", Action: CRDTORSetRemove, Element: "apple"})

	snapshot, err := s.CompactCRDT("doc", "dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if snapshot.Operations != 0 || snapshot.Tombstones != 0 {
		t.Fatalf("after compaction: operations=%d tombstones=%d, want 0/0", snapshot.Operations, snapshot.Tombstones)
	}
	if string(snapshot.Value) != `[]` {
		t.Fatalf("merged value = %s, want []", snapshot.Value)
	}
}

func TestCompactGateAndMissingState(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	registerDevices(t, s, "dev-1", "dev-2")
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a1", DeviceID: "dev-1", Value: rawInt(5)})

	// An unregistered device is rejected before any CRDT content is observed.
	if _, err := s.CompactCRDT("doc", "ghost"); !errors.Is(err, ErrDeviceNotFound) {
		t.Fatalf("unregistered device err = %v, want ErrDeviceNotFound", err)
	}
	// A revoked device is rejected and changes nothing.
	if _, err := s.SetDocumentPermission("doc", "dev-2", false); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CompactCRDT("doc", "dev-2"); !errors.Is(err, ErrPermissionDenied) {
		t.Fatalf("revoked device err = %v, want ErrPermissionDenied", err)
	}
	// A document with no CRDT operation has nothing to compact.
	if _, err := s.CompactCRDT("never", "dev-1"); !errors.Is(err, ErrCRDTNotFound) {
		t.Fatalf("empty document err = %v, want ErrCRDTNotFound", err)
	}
	if _, err := s.GetCRDTSnapshot("never"); !errors.Is(err, ErrCRDTNotFound) {
		t.Fatalf("empty snapshot err = %v, want ErrCRDTNotFound", err)
	}

	// None of the rejections trimmed anything.
	snapshot, err := s.GetCRDTSnapshot("doc")
	if err != nil {
		t.Fatal(err)
	}
	if snapshot.Operations != 1 || string(snapshot.Value) != "5" {
		t.Fatalf("snapshot after rejections = %+v", snapshot)
	}
}

func TestCompactLeavesChangeLogAndSubscribersAlone(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	registerDevices(t, s, "dev-1")

	// A change-log document shares the document id; compaction must not
	// allocate cursors or append changes to it.
	if _, err := s.PostChanges("doc", []Change{{ID: "c1", DeviceID: "dev-1", Payload: json.RawMessage(`{"k":1}`)}}); err != nil {
		t.Fatal(err)
	}
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a1", DeviceID: "dev-1", Value: rawInt(5)})
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a2", DeviceID: "dev-1", Value: rawInt(8)})

	sub, unregister := s.AddCRDTSubscription("doc", "dev-1")
	defer unregister()

	if _, err := s.CompactCRDT("doc", "dev-1"); err != nil {
		t.Fatal(err)
	}

	// No notification: the merged value never moved.
	if queued := sub.Drain(); len(queued) != 0 {
		t.Fatalf("compaction queued %d states, want none", len(queued))
	}
	select {
	case <-sub.Wake():
		t.Fatal("compaction woke a subscriber")
	default:
	}

	// No cursor and no change record: the log still holds exactly c1 at 1.
	changes, next, err := s.ListChanges("doc", 0, 10)
	if err != nil {
		t.Fatal(err)
	}
	if len(changes) != 1 || changes[0].ID != "c1" || next != 1 {
		t.Fatalf("changes after compaction = %+v next=%d", changes, next)
	}
}

func TestCompactConcurrentRunsSerialize(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	registerDevices(t, s, "dev-1", "dev-2")
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a1", DeviceID: "dev-1", Value: rawInt(5)})
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a2", DeviceID: "dev-1", Value: rawInt(8)})

	var wg sync.WaitGroup
	snapshots := make([]CRDTSnapshot, 4)
	for i := range snapshots {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			device := "dev-1"
			if i%2 == 1 {
				device = "dev-2"
			}
			snapshot, err := s.CompactCRDT("doc", device)
			if err != nil {
				t.Errorf("compact %d: %v", i, err)
				return
			}
			snapshots[i] = snapshot
		}(i)
	}
	wg.Wait()
	for i, snapshot := range snapshots {
		if snapshot.Operations != 1 || string(snapshot.Value) != "8" {
			t.Fatalf("snapshot %d = %+v, want one operation merging to 8", i, snapshot)
		}
	}
}

func TestCompactPersistsAcrossReopen(t *testing.T) {
	path := filepath.Join(t.TempDir(), "sync.db")
	s, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	registerDevices(t, s, "dev-1")
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a1", DeviceID: "dev-1", Value: rawInt(5)})
	submitCRDT(t, s, "doc", CRDTTypeCounter, CRDTOp{ID: "a2", DeviceID: "dev-1", Value: rawInt(8)})
	if _, err := s.CompactCRDT("doc", "dev-1"); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	s2, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s2.Close() }()

	snapshot, err := s2.GetCRDTSnapshot("doc")
	if err != nil {
		t.Fatal(err)
	}
	if snapshot.Operations != 1 || snapshot.Tombstones != 0 || string(snapshot.Value) != "8" {
		t.Fatalf("snapshot after reopen = %+v", snapshot)
	}
	// The regression gate survives the restart exactly as before.
	_, err = s2.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
		{ID: "a3", DeviceID: "dev-1", Value: rawInt(7)},
	})
	var conflict *ErrCRDTConflict
	if !errors.As(err, &conflict) {
		t.Fatalf("regression after reopen err = %v, want *ErrCRDTConflict", err)
	}
	// A retained op stays idempotent after the restart.
	results, err := s2.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
		{ID: "a2", DeviceID: "dev-1", Value: rawInt(8)},
	})
	if err != nil || results[0].Created {
		t.Fatalf("retained op replay after reopen = %v %+v, want idempotent", err, results)
	}
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtCompactRequest is the body of POST .../crdt/compact.
type crdtCompactRequest struct {
	DeviceID string `json:"deviceId"`
}

// handleCRDTCompact trims the document's stored CRDT operations and
// tombstones down to the ones still participating in the merge.
//
// The request contract matches the CRDT submission endpoint: strict
// application/json, exactly one JSON value, no trailing content and a
// non-empty deviceId — any violation is a 400 JSON error with zero writes.
// The device gate then applies in the submission's order: an unregistered
// device is a 404, a device whose permission for the document was revoked is
// a 403, and a document with no committed CRDT operation is a 404; none of
// them writes anything or leaks state content.
//
// On success the answer is 200 with the post-compaction snapshot, rendered
// byte-for-byte like a snapshot read immediately afterward (writeCRDTSnapshot).
// Compaction is idempotent — a repeat trims nothing and returns the same
// body — and touches only the CRDT state layer: it allocates no change
// cursor, writes no change record and, because the merged value never moves,
// pushes no notification.
func handleCRDTCompact(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtCompactRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	snapshot, err := s.CompactCRDT(documentID, req.DeviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, store.ErrCRDTNotFound):
			writeError(w, http.StatusNotFound, "crdt state not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact crdt state")
		}
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

// handleCRDTSnapshot returns the document's merged CRDT state together with
// the number of stored operations and tombstones the merge is derived from.
// The read carries no device identity and adds no authentication: like the
// document-level state read it is open, and a document with no committed CRDT
// operation answers the same 404 JSON as the state read. The read is pure —
// no cursor, no change record, no subscription.
func handleCRDTSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	snapshot, err := s.GetCRDTSnapshot(documentID)
	if err != nil {
		if errors.Is(err, store.ErrCRDTNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt snapshot")
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

// writeCRDTSnapshot renders a CRDT snapshot exactly as both snapshot surfaces
// must emit it: compact single-line JSON with the keys in type, value,
// operations, tombstones order, terminated by a newline, so the compaction
// response and the snapshot read can be compared byte-for-byte.
func writeCRDTSnapshot(w http.ResponseWriter, snapshot store.CRDTSnapshot) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(marshalCRDTSnapshot(snapshot))
}

// marshalCRDTSnapshot encodes a CRDT snapshot the single way both surfaces
// emit it: compact single-line JSON with the keys in type, value, operations,
// tombstones order and one trailing newline. The merged value is embedded as
// native JSON (a number, an array, or a register's arbitrary JSON value)
// rather than an escaped blob, and the two counts are non-negative integers.
// The key order is fixed by construction — not by the encoder's map ordering
// — so the bytes are stable across every reader.
func marshalCRDTSnapshot(snapshot store.CRDTSnapshot) []byte {
	var buf strings.Builder
	typeRaw, _ := json.Marshal(snapshot.Type)
	buf.WriteString(`{"type":`)
	_, _ = buf.Write(typeRaw)
	buf.WriteString(`,"value":`)
	_, _ = buf.Write(snapshot.Value)
	buf.WriteString(`,"operations":`)
	buf.WriteString(strconv.FormatInt(snapshot.Operations, 10))
	buf.WriteString(`,"tombstones":`)
	buf.WriteString(strconv.FormatInt(snapshot.Tombstones, 10))
	buf.WriteString("}\n")
	return []byte(buf.String())
}

